push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
	push("全部🌊分类", null, 1, 1);
	arList = [["全部🌊类型","/manga"],["人气🌊推荐","/hots"],["热门🌊推荐","/dayup"],["最新🌊上架","/newss"]];
arList.map(([title, uri]) => {
  let url = `${uri}<,/page/{{page+1}}>`;
  push(title, url, 1, 0.35);
