//初始化源变量
function csh() {
    const {
        java,
        source
    } = this;
    var original = {
        "orderBy": "人气",
        "isfinish": "连载",
        "size": "全部",
        "sort": "🎆玄幻🎆"
    };
    var csh_1;
    //设置默认的源变量
    try {

        csh_1 = JSON.parse(source.getVariable());
        if (csh_1 == null) {
            error;
        } else {
            '';
        };
    } catch (e) {
        csh_1 = original;
        source.setVariable(JSON.stringify(csh_1, null, 2));
        java.toast("初始化成功")
    }

}



//获取源变量的值
function Get(e) {
    const {
        java,
        source,
        cookie
    } = this;
    var get = JSON.parse(source.getVariable());
    return get[e];
}

//按钮切换时改变源变量并刷新发现
function show(m, t) {
    const {
        java,
        source
    } = this;
    //源变量为空时刷新发现，重置源变量
    source.getVariable()==''?java.refreshExplore():'';//
    var data = JSON.parse(source.getVariable());
    //java.log(data);
    data[t] = m;
    //java.log(JSON.stringify(data));
    source.setVariable(JSON.stringify(data, null, 2));
    java.refreshExplore();
}

/**
 * 创建筛选器配置
 * @param {string} title - 筛选器标题
